#!/usr/bin/env node
// Regenerates the self-hosted font modules (GL#123; Nunito Sans since #40) so no Worker page loads
// fonts from Google. Each target gets a TypeScript module holding its woff2 subsets as base64
// (the repo's existing pattern for binary assets, see member-portal/src/assets/favicon.ts), plus
// the fonts' SIL OFL licence files beside it.
//
//   node scripts/build-font-modules.mjs
//
// Needs npm and network access: it runs `npm pack` for the pinned Fontsource packages below into
// a temporary directory. Bump a version here, re-run, and commit the regenerated files.

import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// A variable package (`variable: true`) ships one file per subset and style that covers every
// weight in its range, which is smaller than the static files for the four weights the pages use.
export const PACKAGES = {
  'Nunito Sans': { name: '@fontsource-variable/nunito-sans', version: '5.3.0', slug: 'nunito-sans', variable: true },
  Poppins: { name: '@fontsource/poppins', version: '5.3.0', slug: 'poppins' },
};

// Only the weights and styles each page uses, and the subsets its languages need. The browser
// downloads a file only when the page has a character in its unicode-range in that face.
export const TARGETS = [
  {
    // Portal locales include Vietnamese (Nunito Sans has a vietnamese subset) and Hindi: Nunito
    // Sans has no Devanagari, so Poppins's devanagari subset stays as the Hindi fallback. CJK
    // locales fall back to the system stack. Italic is for the letters (letterViews.ts).
    out: 'member-portal/src/assets/fontData.ts',
    faces: {
      'Nunito Sans': { styles: ['normal', 'italic'], subsets: ['latin', 'latin-ext', 'vietnamese'] },
      Poppins: { weights: [400, 600, 700], subsets: ['devanagari'] },
    },
  },
  {
    // The widget is English-only and sets no italic.
    out: 'svbc-calendars/src/fontData.ts',
    faces: {
      'Nunito Sans': { styles: ['normal'], subsets: ['latin', 'latin-ext'] },
    },
  },
  {
    // The staff status page is English-only and sets no italic.
    out: 'status-page/src/fontData.ts',
    faces: {
      'Nunito Sans': { styles: ['normal'], subsets: ['latin'] },
    },
  },
];

/**
 * The Fontsource file stem for one face, also used as its served file name.
 * @param {{ slug: string, variable?: boolean }} pkg
 * @param {{ subset: string, weight?: number, style: string }} face
 */
export function faceId(pkg, { subset, weight, style }) {
  return `${pkg.slug}-${subset}-${pkg.variable ? 'wght' : weight}-${style}`;
}

/**
 * @param {{ source: string, faces: Array<{ id: string, family: string, weight: string, style: string, subset: string, unicodeRange: string, base64: string }> }} input
 * @returns {string} the TypeScript module text
 */
export function renderFontModule({ source, faces }) {
  const families = [...new Set(faces.map((f) => `'${f.family}'`))].join(' | ');
  const entries = faces
    .map(
      (f) =>
        `  {\n    id: '${f.id}',\n    family: '${f.family}',\n    weight: '${f.weight}',\n    style: '${f.style}',\n` +
        `    subset: '${f.subset}',\n    unicodeRange: '${f.unicodeRange}',\n    woff2Base64:\n      '${f.base64}',\n  },`
    )
    .join('\n');
  return `// Generated by scripts/build-font-modules.mjs from ${source}. Do not edit; re-run the script.
// SIL Open Font License 1.1: see the OFL-*.txt files beside this module.

export interface EmbeddedFont {
  /** Fontsource file stem, unique per face: the served file name. */
  id: string;
  family: ${families};
  /** A CSS font-weight descriptor: one weight, or a variable font's range ('200 1000'). */
  weight: string;
  style: 'normal' | 'italic';
  subset: string;
  unicodeRange: string;
  woff2Base64: string;
}

export const EMBEDDED_FONTS: readonly EmbeddedFont[] = [
${entries}
];
`;
}

// The weight range a variable package covers, from its metadata.json ({ variable: { wght: { min, max } } }).
function variableRange(dir) {
  const { wght } = JSON.parse(readFileSync(join(dir, 'metadata.json'), 'utf8')).variable;
  return `${wght.min} ${wght.max}`;
}

function main() {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..');
  const work = mkdtempSync(join(tmpdir(), 'svbc-fonts-'));
  try {
    const dirs = {};
    for (const [family, pkg] of Object.entries(PACKAGES)) {
      const tgz = execFileSync('npm', ['pack', `${pkg.name}@${pkg.version}`, '--silent'], { cwd: work, encoding: 'utf8' }).trim();
      const dir = join(work, pkg.slug);
      execFileSync('mkdir', ['-p', dir]);
      execFileSync('tar', ['-xzf', join(work, tgz), '-C', dir]);
      dirs[family] = join(dir, 'package');
    }
    for (const target of TARGETS) {
      const faces = [];
      for (const [family, spec] of Object.entries(target.faces)) {
        const pkg = PACKAGES[family];
        const ranges = JSON.parse(readFileSync(join(dirs[family], 'unicode.json'), 'utf8'));
        const variants = pkg.variable
          ? spec.styles.map((style) => ({ style, weight: undefined }))
          : spec.weights.map((weight) => ({ style: 'normal', weight }));
        for (const { style, weight } of variants) {
          for (const subset of spec.subsets) {
            if (!ranges[subset]) throw new Error(`${family} has no ${subset} subset`);
            const id = faceId(pkg, { subset, weight, style });
            const base64 = readFileSync(join(dirs[family], 'files', `${id}.woff2`)).toString('base64');
            faces.push({ id, family, weight: pkg.variable ? variableRange(dirs[family]) : String(weight), style, subset, unicodeRange: ranges[subset], base64 });
          }
        }
      }
      const source = Object.keys(target.faces)
        .map((family) => `${PACKAGES[family].name}@${PACKAGES[family].version}`)
        .join(' and ');
      const out = join(root, target.out);
      writeFileSync(out, renderFontModule({ source, faces }));
      for (const family of Object.keys(target.faces)) {
        copyFileSync(join(dirs[family], 'LICENSE'), join(dirname(out), `OFL-${PACKAGES[family].slug}.txt`));
      }
      console.log(`wrote ${target.out} (${faces.length} faces)`);
    }
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
